const byId = new Map(STICKER_PACKS.flatMap((p) => p.items.map((i) => [i.id, i.xml] as const)));
/** SVG стикера по id «набор/имя»; нет такого — undefined. */
export const stickerXml = (id: string) => byId.get(id);
export const packName = (id?: string) => STICKER_PACKS.find((p) => p.id === id)?.name;
